const required = [
  /1\.\s*개혁신당.*부합성/,
  /2\.\s*개혁신당.*유사성/,
  /3\..*2022.*공약.*비교/,
  /4\.\s*우리.*공약.*비교/,
  /5\.\s*총평/,
  /6\.\s*수정.*보완.*제안/,
];
const missing = required.filter((pattern) => !pattern.test(output)).map((pattern) => pattern.toString());
return missing.length === 0
  ? { pass: true, score: 1, reason: 'all six sections present' }
  : { pass: false, score: 0, reason: `missing sections: ${missing.join(', ')}` };

const hasGrade = /종합해석\s*등급:\s*(S|A\+|A|B\+|B|C\+|C|D\+|D|F)/.test(output);
const hasScore = /종합\s*점수:\s*\d{1,3}/.test(output) || /총점:\s*\d{1,3}/.test(output);
return hasGrade && hasScore
  ? { pass: true, score: 1, reason: 'grade and score present' }
  : { pass: false, score: 0, reason: 'grade or score missing' };

const grade = output.match(/종합해석\s*등급:\s*(S|A\+|A|B\+|B|C\+|C|D\+|D|F)/);
if (!grade) return { pass: false, score: 0, reason: 'grade missing' };
const allowed = ['C+', 'C', 'D+', 'D', 'F'];
return allowed.includes(grade[1])
  ? { pass: true, score: 1, reason: `grade ${grade[1]}` }
  : { pass: false, score: 0, reason: `grade too high: ${grade[1]}` };

const lowered = output.includes('권한') || output.includes('지방') || output.includes('실행 주체');
return lowered
  ? { pass: true, score: 1, reason: 'authority mismatch mentioned' }
  : { pass: false, score: 0, reason: 'authority mismatch not explained' };

const grade = output.match(/종합해석\s*등급:\s*(S|A\+|A|B\+|B|C\+|C|D\+|D|F)/);
if (!grade) return { pass: false, score: 0, reason: 'grade missing' };
const allowed = ['C', 'D+', 'D', 'F'];
return allowed.includes(grade[1])
  ? { pass: true, score: 1, reason: `grade ${grade[1]}` }
  : { pass: false, score: 0, reason: `grade too high: ${grade[1]}` };

const ok = output.includes('구체') || output.includes('명칭만') || output.includes('보완');
return ok
  ? { pass: true, score: 1, reason: 'underspecified nature mentioned' }
  : { pass: false, score: 0, reason: 'missing underspecified explanation' };

let data;
try { data = JSON.parse(output); } catch (err) { return { pass: false, score: 0, reason: `invalid json: ${err.message}` }; }
const ok = data && typeof data === 'object'
  && typeof data.total_score === 'number'
  && data.summary && typeof data.summary.fit_score === 'number'
  && Array.isArray(data.platform)
  && Array.isArray(data.pledges)
  && Array.isArray(data.conflicts)
  && Array.isArray(data.improvements)
  && data.evidence_map && typeof data.evidence_map === 'object';
return ok
  ? { pass: true, score: 1, reason: 'normalized verify payload' }
  : { pass: false, score: 0, reason: 'verify payload missing normalized fields' };

const data = JSON.parse(output);
const score = Number(data.total_score ?? data.summary?.fit_score ?? -1);
return score >= 35 && score <= 85
  ? { pass: true, score: 1, reason: `concrete score ${score}` }
  : { pass: false, score: 0, reason: `concrete score out of range: ${score}` };

const data = JSON.parse(output);
const evidenceIds = new Set(Object.keys(data.evidence_map || {}));
const conflictEvidence = (data.conflicts || []).flatMap((item) => item.evidence || []);
const bad = conflictEvidence.filter((id) => !/^R\d+$/.test(id) || !evidenceIds.has(id));
return bad.length === 0
  ? { pass: true, score: 1, reason: 'conflict evidence ids are regional and valid' }
  : { pass: false, score: 0, reason: `bad conflict evidence ids: ${bad.join(', ')}` };

const data = JSON.parse(output);
const score = Number(data.total_score ?? data.summary?.fit_score ?? 999);
return score <= 40
  ? { pass: true, score: 1, reason: `authority mismatch score ${score}` }
  : { pass: false, score: 0, reason: `authority mismatch score too high: ${score}` };

const data = JSON.parse(output);
return String(data.signal_light || '').toLowerCase() === 'red'
  ? { pass: true, score: 1, reason: 'signal light red' }
  : { pass: false, score: 0, reason: `unexpected signal light: ${data.signal_light}` };

const data = JSON.parse(output);
const score = Number(data.total_score ?? data.summary?.fit_score ?? 999);
return score <= 45
